using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TMPro;using TutorialFramework;
[DefaultExecutionOrder(10000)]public class CameraLateUpdateProbe:MonoBehaviour{
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;public SmoothCameraMovement mover;public bool done;public string result;int lateWrites;Vector3 updatePosition;Quaternion updateRotation;bool observing;
 void Update(){if(observing){updatePosition=mover.transform.position;updateRotation=mover.transform.rotation;}}
 void LateUpdate(){if(observing&&(Vector3.Distance(updatePosition,mover.transform.position)>.00001f||Quaternion.Angle(updateRotation,mover.transform.rotation)>.001f))lateWrites++;}
 static void Require(bool b,string m){if(!b)throw new Exception(m);}static void Set(SmoothCameraMovement m,string key,object value)=>typeof(SmoothCameraMovement).GetField(key,flags).SetValue(m,value);
 static void Request(SmoothCameraMovement m,int i){var p=m.transform.position;var q=m.transform.rotation;m.MoveToPosition(i);Require(m.transform.position==p&&m.transform.rotation==q,"Request wrote pose before LateUpdate");}
 static void At(SmoothCameraMovement m,Transform t){Require(Vector3.Distance(m.transform.position,t.position)<.0001f&&Quaternion.Angle(m.transform.rotation,t.rotation)<.01f,"Wrong final camera pose");}
 public void Begin(SmoothCameraMovement source){mover=source;StartCoroutine(Check());}
 IEnumerator Check(){var routine=Checks();while(true){bool next;try{next=routine.MoveNext();}catch(Exception e){result="FAIL "+e;done=true;yield break;}if(!next)break;yield return routine.Current;}result="PASS: all saved views, no immediate pose writes, movement observed after Update, interruption/latest request, invalid index, label, zero/negative duration, disable/re-enable and destroyed target.";done=true;}
 IEnumerator Checks(){var positions=(List<Transform>)typeof(SmoothCameraMovement).GetField("cameraPositions",flags).GetValue(mover);float duration=(float)typeof(SmoothCameraMovement).GetField("moveDuration",flags).GetValue(mover);var label=(TMP_Text)typeof(SmoothCameraMovement).GetField("cameraNumberText",flags).GetValue(mover);Require(duration>0f,"Expected positive authored duration");Set(mover,"moveDuration",.08f);observing=true;foreach(int i in Enumerable.Range(0,positions.Count)){Request(mover,i);if(label)Require(label.text==(i+1).ToString("D2"),"Camera label changed");yield return new WaitForSeconds(.15f);At(mover,positions[i]);}Require(lateWrites>0,"No LateUpdate-phase movement observed");
 Set(mover,"moveDuration",duration);Request(mover,0);yield return new WaitForSeconds(duration*.45f);Require(Vector3.Distance(mover.transform.position,positions[0].position)>.0001f,"Transition completed before authored duration");yield return new WaitForSeconds(duration*.6f+.05f);At(mover,positions[0]);Set(mover,"moveDuration",.08f);Request(mover,0);yield return null;Request(mover,positions.Count-1);yield return new WaitForSeconds(.15f);At(mover,positions.Last());Request(mover,-1);Request(mover,positions.Count);At(mover,positions.Last());Set(mover,"moveDuration",duration);observing=false;
 // Use disposable objects for edge cases; authored transforms are never changed.
 var go=new GameObject("Camera LateUpdate edge test");var edge=go.AddComponent<SmoothCameraMovement>();var a=new GameObject("Transient camera target A").transform;var b=new GameObject("Transient camera target B").transform;a.position=new Vector3(3,4,5);b.position=new Vector3(8,9,10);Set(edge,"cameraPositions",new List<Transform>{a,b});Set(edge,"moveDuration",0f);Request(edge,0);yield return null;At(edge,a);Set(edge,"moveDuration",-.1f);Request(edge,1);yield return null;At(edge,b);
 Set(edge,"moveDuration",.2f);Request(edge,0);yield return null;edge.enabled=false;var stopped=edge.transform.position;yield return new WaitForSeconds(.25f);Require(edge.transform.position==stopped,"Disabled component moved camera");edge.enabled=true;yield return null;Require(edge.transform.position==stopped,"Old transition resumed after re-enable");Request(edge,1);UnityEngine.Object.DestroyImmediate(b.gameObject);yield return new WaitForSeconds(.25f);Require(edge.transform.position==stopped,"Destroyed target caused movement");UnityEngine.Object.Destroy(a.gameObject);UnityEngine.Object.Destroy(go);
 }
}
[InitializeOnLoad]public static class CameraLateUpdateTest{
 const string P="CameraLateUpdateTest.";const string report="Temp/CameraLateUpdate/runtime.txt";static readonly string[] ids={"Speed Curve Characteristics","Regulating DC Output from Wind Turbine using PWM Charger","Regulating DC Output from Wind Turbine using MPPT Charger","OFF Grid System Using Wind Turbine"};static bool Running{get=>SessionState.GetBool(P+"run",false);set=>SessionState.SetBool(P+"run",value);}static int Stage{get=>SessionState.GetInt(P+"stage",0);set=>SessionState.SetInt(P+"stage",value);}static int Index{get=>SessionState.GetInt(P+"index",0);set=>SessionState.SetInt(P+"index",value);}static double Due{get=>SessionState.GetFloat(P+"due",0);set=>SessionState.SetFloat(P+"due",(float)value);}static CameraLateUpdateProbe probe;
 static CameraLateUpdateTest(){EditorApplication.update+=Tick;Application.logMessageReceived+=(m,s,t)=>{if(Running&&(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)){File.AppendAllText(report,"ERROR "+m+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);}};}
 static void Tick(){if(!Running&&File.Exists("Temp/camera-lateupdate-test.flag")&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating){File.Delete("Temp/camera-lateupdate-test.flag");if(SceneManager.GetActiveScene().isDirty){File.WriteAllText(report,"BLOCKED unsaved scene");return;}File.WriteAllText(report,"");Running=true;Stage=Index=0;SessionState.SetInt(P+"errors",0);EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");Due=EditorApplication.timeSinceStartup+6;EditorApplication.EnterPlaymode();return;}if(!Running||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<Due)return;
 try{if(Stage==5){if(EditorApplication.isPlayingOrWillChangePlaymode)return;EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");File.AppendAllText(report,"COMPLETE errors="+SessionState.GetInt(P+"errors",0)+"\n");Running=false;return;}var manager=InteractionManager.Instance;if(!manager){Due=EditorApplication.timeSinceStartup+1;return;}if(Stage==0){manager.currentMode=ExperimentMode.Guided;var launcher=Resources.FindObjectsOfTypeAll<MainMenuExperimentLauncher>().Single(l=>l.gameObject.scene==SceneManager.GetActiveScene()&&new SerializedObject(l).FindProperty("storyboardId").stringValue==ids[Index]);launcher.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Stage=1;Due=EditorApplication.timeSinceStartup+7;return;}
 if(Stage==1||Stage==3){var mover=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<SmoothCameraMovement>(true)).Single();probe=mover.gameObject.AddComponent<CameraLateUpdateProbe>();probe.Begin(mover);Stage++;return;}
 if(Stage==2||Stage==4){if(!probe||!probe.done)return;File.AppendAllText(report,"EXP"+(Index+1)+" "+(Stage==2?"Guided":"Free")+" "+probe.result+"\n");if(probe.result.StartsWith("FAIL"))throw new Exception(probe.result);UnityEngine.Object.Destroy(probe);if(Stage==2){manager.SetFree();Stage=3;Due=EditorApplication.timeSinceStartup+8;}else{Index++;if(Index==4){Stage=5;EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else{manager.ReturnToExperimentMenu();Stage=0;Due=EditorApplication.timeSinceStartup+6;}}}
 }catch(Exception e){File.AppendAllText(report,"FAIL "+e+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);Stage=5;if(EditorApplication.isPlaying){EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else Running=false;}}
}

